import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict with side, price(None for market), qty remaining, time, active
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    time_counter = 0

    def clean_buy():
        while buy_heap:
            neg_price, t, oid = buy_heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, t, oid = sell_heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        t = time_counter
        time_counter += 1

        if side == 'buy':
            # match against sells
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                s_price, s_time, s_id = sell_heap[0]
                if typ != 'market' and price < s_price:
                    break
                s_info = orders_info[s_id]
                trade_qty = min(remaining, s_info['qty'])
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                s_info['qty'] -= trade_qty
                if s_info['qty'] <= 0:
                    s_info['active'] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                orders_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': t, 'active': True}
                heapq.heappush(buy_heap, (-price, t, oid))
            else:
                # discard remainder, but if limit fully filled, still record info as inactive/filled (not needed)
                if typ == 'limit':
                    orders_info[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'time': t, 'active': False}
                else:
                    orders_info[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'time': t, 'active': False}
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                neg_price, b_time, b_id = buy_heap[0]
                b_price = -neg_price
                if typ != 'market' and price > b_price:
                    break
                b_info = orders_info[b_id]
                trade_qty = min(remaining, b_info['qty'])
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                b_info['qty'] -= trade_qty
                if b_info['qty'] <= 0:
                    b_info['active'] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                orders_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': t, 'active': True}
                heapq.heappush(sell_heap, (price, t, oid))
            else:
                orders_info[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'time': t, 'active': False}

    return trades

